// AppLayout.jsx  —  layout principal atualizado
// Mudanças:
//   • Botão de logout no rodapé da sidebar (vermelho)
//   • Ícone de notificação no topbar (com badge pulsante)
//   • Perfil do usuário no header à direita (nome + cargo)
//   • Configurações removidas da sidebar

import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';

const NAV_ITEMS = [
  { path: '/',          icon: 'dashboard',        label: 'Dashboard'  },
  { path: '/projects',  icon: 'rocket_launch',    label: 'Projetos'   },
  { path: '/tasks',     icon: 'task_alt',         label: 'Tarefas'    },
  { path: '/team',      icon: 'groups',           label: 'Equipe'     },
  { path: '/reports',   icon: 'bar_chart',        label: 'Relatórios' },
];

function initials(name = '') {
  return name
    .split(' ')
    .slice(0, 2)
    .map(w => w[0])
    .join('')
    .toUpperCase();
}

export default function AppLayout({ children }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [notifCount] = useState(3); // substitua por dado real

  return (
    <div className="app-layout">

      {/* ── SIDEBAR ─────────────────────────────────────────────────────── */}
      <aside className="sidebar">

        {/* Logo */}
        <div className="sidebar-logo">
          <div className="sidebar-logo-icon">🚀</div>
          <div className="sidebar-logo-text">
            <strong>ProjectHub</strong>
            <span>Workspace</span>
          </div>
        </div>

        {/* Nav links */}
        <nav className="sidebar-nav">
          {NAV_ITEMS.map(item => (
            <button
              key={item.path}
              className={`nav-item ${location.pathname === item.path ? 'active' : ''}`}
              onClick={() => navigate(item.path)}
            >
              <span className="material-icons nav-icon">{item.icon}</span>
              {item.label}
            </button>
          ))}
        </nav>

        {/* Footer — somente logout */}
        <div className="sidebar-footer">
          <button className="sidebar-logout-btn" onClick={logout}>
            <span className="material-icons nav-icon">logout</span>
            Sair
          </button>
        </div>
      </aside>

      {/* ── MAIN ────────────────────────────────────────────────────────── */}
      <div className="main-content">

        {/* ── TOPBAR ──────────────────────────────────────────────────── */}
        <header className="topbar">
          {/* Hamburger (mobile) */}
          <button className="topbar-menu-btn">
            <span className="material-icons" style={{ fontSize: 18 }}>menu</span>
          </button>

          {/* Search */}
          <div className="topbar-search">
            <span className="topbar-search-icon material-icons" style={{ fontSize: 15 }}>search</span>
            <input placeholder="Pesquisar projetos, tarefas…" />
          </div>

          {/* Right side */}
          <div className="topbar-right">

            {/* 🔔 Notificações */}
            <button className="topbar-icon-btn" title="Notificações">
              <span className="material-icons" style={{ fontSize: 18 }}>notifications</span>
              {notifCount > 0 && (
                <span className="notif-badge">{notifCount > 9 ? '9+' : notifCount}</span>
              )}
            </button>

            {/* Perfil do usuário */}
            <div className="topbar-user" onClick={() => navigate('/profile')}>
              <div className="avatar">
                {user?.avatar || initials(user?.name || 'U')}
              </div>
              <div className="topbar-user-info">
                <span className="topbar-user-name">
                  {user?.name?.split(' ')[0] || 'Usuário'}
                </span>
                <span className="topbar-user-role">
                  {user?.role || 'Membro'}
                </span>
              </div>
              <span className="material-icons" style={{ fontSize: 14, color: 'rgba(255,255,255,0.35)', marginLeft: 2 }}>
                expand_more
              </span>
            </div>
          </div>
        </header>

        {/* ── PAGE CONTENT ────────────────────────────────────────────── */}
        <main className="page-content">
          {children}
        </main>
      </div>
    </div>
  );
}
